package org.rsmod.content.travel.charter

/** Charter destinations and fares generated by `tools/travel/charter_to_tsv.py` from the OSRS Wiki. */
internal object CharterData {
    class Destination(val key: String, val name: String, val x: Int, val z: Int)

    class Fare(val from: String, val to: String, val coins: Int)

    val destinations: List<Destination> by lazy {
        rows("dest").map { Destination(it[1], it[2], it[3].toInt(), it[4].toInt()) }
    }

    val fares: List<Fare> by lazy { rows("fare").map { Fare(it[1], it[2], it[3].toInt()) } }

    private val lines: List<List<String>> by lazy {
        val input =
            CharterData::class.java.getResourceAsStream("charter.tsv")
                ?: error("Charter resource not found: charter.tsv")
        input.bufferedReader().use { it.readLines() }
            .map { it.trimEnd() }
            .filter { it.isNotBlank() && !it.startsWith("#") }
            .map { it.split('\t') }
    }

    private fun rows(kind: String): List<List<String>> = lines.filter { it[0] == kind }
}
